import os, shutil, zipfile, re
out='/root/clinic_intake_ready.hwpx'
verify_dir='/tmp/hwpx_verify'
if os.path.exists(verify_dir):
    shutil.rmtree(verify_dir)
os.makedirs(verify_dir, exist_ok=True)
with zipfile.ZipFile(out,'r') as z:
    z.extractall(verify_dir)

# 1) no placeholders
hits=[]
for root, dirs, files in os.walk(verify_dir):
    for f in files:
        p=os.path.join(root,f)
        try:
            data=open(p,'rb').read()
        except Exception:
            continue
        if b'{{' in data:
            hits.append(p)
print('placeholder_files:', hits)

# 2) age note
age_hits=[]
for root, dirs, files in os.walk(verify_dir):
    for f in files:
        p=os.path.join(root,f)
        if not p.endswith('.xml') and not p.endswith('.hpf'):
            continue
        try:
            txt=open(p,'r',encoding='utf-8').read()
        except Exception:
            continue
        if '세)' in txt:
            age_hits.append(p)
print('age_note_files:', age_hits)

# 3) phone pattern
phone_re=re.compile(r'\b\d{3}-\d{4}-\d{4}\b')
phone_hits=[]
for root, dirs, files in os.walk(verify_dir):
    for f in files:
        p=os.path.join(root,f)
        if not p.endswith('.xml') and not p.endswith('.hpf'):
            continue
        try:
            txt=open(p,'r',encoding='utf-8').read()
        except Exception:
            continue
        if phone_re.search(txt):
            phone_hits.append(p)
print('phone_files:', phone_hits)

# 4) signature note preserved
sig_hits=[]
for root, dirs, files in os.walk(verify_dir):
    for f in files:
        p=os.path.join(root,f)
        if not p.endswith('.xml') and not p.endswith('.hpf'):
            continue
        try:
            txt=open(p,'r',encoding='utf-8').read()
        except Exception:
            continue
        if '서명' in txt or '자필' in txt:
            sig_hits.append(p)
print('signature_files:', sig_hits)

# 5) ensure no lineseg/linesegarray remain in section0.xml
sec=os.path.join(verify_dir,'Contents','section0.xml')
sec_txt=open(sec,'r',encoding='utf-8').read()
print('contains_lineseg:', ('lineseg' in sec_txt.lower()))
